      // Live website component hierarchy; prototype data and services only.
      const live={voice:'idle',voiceText:'',handsFree:false,readAloud:true,about:(s.turns||[]).at(-1)?.about||null,pages:{},payments:{},search:'',preTab:s.preReadTab||'overview',week:'all',month:9,year:2026,org:'',jump:null};
      const CPT={Appendectomy:['44970','Laparoscopic appendectomy'],Bariatric:['43775','Laparoscopic sleeve gastrectomy'],Cholecystectomy:['47562','Laparoscopic cholecystectomy'],'Fundoplication / hiatal hernia':['43280','Laparoscopic fundoplasty'],Gastrectomy:['43631','Partial gastrectomy'],'Lysis of adhesions':['44180','Laparoscopic enterolysis'],'Small-bowel resection':['44202','Laparoscopic enterectomy'],Splenectomy:['38120','Laparoscopic splenectomy'],Colectomy:['44204','Laparoscopic partial colectomy'],'OB-GYN':['58571','Laparoscopic total hysterectomy'],Urology:['55866','Laparoscopic radical prostatectomy'],'Inguinal hernia':['49650','Laparoscopic initial inguinal hernia repair'],'Ventral hernia':['49591','Anterior abdominal hernia repair']};
      const cash=n=>'$'+Number(n).toFixed(1)+'M';
      function proPayments(e){const h=e.kind==='hco',total=h?126000:24800,robot=h?76000:18200;return `<p class="fp-small fp-muted">CMS Open Payments · 2025${h?' · doctors based at this account':''}</p><div class="live-kpis">${metric("Competitors’ robots",'$'+fmt(robot),h?'to 3 doctors':'Intuitive Surgical')}${metric('Your robots',h?'$4,200':'$0','Monarch')}</div><h3 class="fp-gap">Robot payments by company · 2025</h3>${liveTable(['Company / robot','Paid'],[['Intuitive Surgical<small>da Vinci, Ion</small>','$'+fmt(robot*.88)],['Distalmotion<small>Dexter</small>','$'+fmt(robot*.12)],['Johnson & Johnson<small>Monarch · yours</small>',h?'$4,200':'$0']])}<p class="fp-small fp-muted">$0 from CMR (Versius), Virtual Incision (MIRA), Karl Storz (Senhance) and Medtronic (Hugo).</p>${h?'<h3 class="fp-gap">Who competitors pay · 2025</h3>'+liveTable(['Doctor / company','Paid'],allHcp.filter(p=>p.site===e.id).map((p,i)=>[link(esc(p.name),'entity:'+p.id)+'<small>Intuitive Surgical</small>','$'+fmt(robot*(i?.35:.65))])):''}<h3 class="fp-gap">All companies · 2025</h3><div class="live-payment-total"><strong>$${fmt(total)}</strong><span>general payments · illustrative records</span></div>${liveTable(['Company','Paid'],[['Intuitive Surgical','$'+fmt(robot*.88)],['Distalmotion','$'+fmt(robot*.12)],['Other companies','$'+fmt(total-robot)]])}<details><summary class="cursor-interaction">How this is counted</summary><p>General payments such as meals, consulting, speaking and travel; not research. Robot figures count robot payments only. Orthopaedic robots are excluded. Sample amounts and fictional clinicians.</p></details>`;}
      const lc=(key,title,sub,body,actions='')=>`<section class="live-card" id="${design}-${key}"><div class="live-cardhead"><div><h2>${title}</h2>${sub?`<p>${esc(sub)}</p>`:''}</div>${actions}</div>${body}</section>`;
      const proTab=()=>s.source==='new'?'explore-'+s.kind:(s.view==='assigned'?'my-':'explore-')+s.kind;
      const qr=(names,values)=>names.map((n,i)=>detail(n,values[i])).join('');
      function liveTable(headers,rows){return `<div class="live-table" role="table"><div class="live-tr live-th" role="row" style="--cols:${headers.length}">${headers.map(h=>`<span role="columnheader">${esc(h)}</span>`).join('')}</div>${rows.map(r=>`<div class="live-tr" role="row" style="--cols:${headers.length}">${r.map((c,i)=>`<span role="cell" ${i?'class="live-num"':''}>${c}</span>`).join('')}</div>`).join('')}</div>`;}
      function codesControl(compact=false){if(compact)return `<div class="live-scopebar"><span class="fp-small fp-muted">Code scope</span>${b(esc(s.group)+icon('chevron-down'),'all-codes','soft')}<span class="fp-small fp-muted">2025</span></div>`;return `<div class="live-codes"><span class="fp-kicker">Specialty</span><div class="fp-pills">${groups.slice(0,4).map(g=>`<button class="fp-pill cursor-interaction" data-act="group:${g}" aria-pressed="${s.group===g}">${g}</button>`).join('')}${b('+ '+(groups.length-4)+' more','all-codes')}</div>${!groups.slice(0,4).includes(s.group)?tag(s.group,'blue'):''}</div>`;}
      function liveShortcuts(){return `${b(icon('sparkles')+'Ask anything, or search your accounts and HCPs','unified-search','fp-askbar')}<div class="fp-shortcuts">${b(icon('map-pinned')+'<span class="fp-scope-text">'+(s.source==='new'?'Someone new':'My territories · '+esc(getScope(s)))+'</span>'+icon('chevron-down'),'scope')}${b(icon('route')+(s.routeStarted?'Resume work':'Route'+(s.routeDate!==TODAY?' · '+stamp(s.routeDate):'')+' · '+s.selected.length),s.routeStarted?'resume:'+s.currentVisit:'route')}</div><div class="live-sectionline live-create-line">${link('+ Create territory','territory-new')}${link('Manage territories','territories')}</div>`;}
      function liveSummary(){const m=scopeMetrics(s),book=allHco.filter(e=>s.membership[e.id]===s.territory),money=book.reduce((n,e)=>n+(e.leakingMoney||0)*factor(s),0);return `<div class="live-greeting"><div class="fp-kicker">${esc(getScope(s))}</div><h1>Good morning, Alex.</h1></div><section class="live-book" aria-label="FieldPro measured summary"><div class="live-book-grid">${[['LEAKING',cash(money),'left since 2022 · '+book.length+' measured'],['VOLUME',fmt(m.volume),'procedures · '+s.group+' · 2025'],['LEAKAGE',m.rate+'%','left in 2025 · '+book.length+' measured'],['TREND',(m.trend==='—'?'—':'+'+m.trend+'%'),'volume, 2025 vs 2024']].map(([k,v,n])=>`<div><span>${k}</span><strong>${v}</strong><small>${esc(n)}</small></div>`).join('')}</div><div class="live-measured"><span>MEASURED ON</span>${tag(s.group==='All codes'?'Assigned procedure codes':s.group)}${link('View codes','all-codes')}</div></section>`;}
      function liveTargetRow(e){const selected=s.selected.includes(e.id),h=e.kind==='hco',site=S(e.id);return `<div class="live-target ${selected?'is-picked':''}"><div class="fp-flex"><button class="fp-check cursor-interaction" data-act="select:${e.id}" aria-label="Select ${esc(e.name)} for route" aria-pressed="${selected}">${icon(selected?'check':'plus')}</button><button class="fp-row-main cursor-interaction" data-act="entity:${e.id}"><strong>${esc(e.name)} ${icon('chevron-right')}</strong><small>${h?esc(e.type+' · '+e.city+', '+e.state):esc(e.specialty+' · '+site.name)}</small></button></div><div class="live-targetmetrics">${metric(h?'Procedures 2025':'Claims 2025',fmt(vol(e,s)),e.trend+'% YoY')}${metric(h?'Opportunity 2025':'Referred in',h?cash(e.opportunity*factor(s)):fmt(Math.round(vol(e,s)*1.16)),h?(e.left/e.volume*100).toFixed(1)+'% left':'selected codes')}</div><div class="fp-flex fp-spread fp-wrap"><span>${tag(membershipLabel(e,s)?'Assigned · '+membershipLabel(e,s):'Not in your targets',membershipLabel(e,s)?'blue':'')}${s.source==='new'?tag('≈ '+distance(e,s).toFixed(1)+' mi'):''}</span>${link(membershipLabel(e,s)?'Manage territory':'+ Add to territory','assign:'+e.id)}</div></div>`;}
      function Vtargets(){const rows=scoped(s);return `${liveShortcuts()}${codesControl()}${s.source==='new'?'<h1>Explore targets</h1>':liveSummary()}<section class="live-results"><div class="live-tabs" role="tablist" aria-label="Targets and exploration">${[['my-hco','My HCOs'],['my-hcp','My HCPs'],['explore-hco','Explore HCOs'],['explore-hcp','Explore HCPs']].map(([k,l])=>`<button role="tab" aria-selected="${proTab()===k}" class="cursor-interaction" data-act="protab:${k}">${l}</button>`).join('')}</div><div class="live-sectionline">${b('Plan my route','route-selection','primary')}${b('+ Add targets','add-targets')}</div><div class="fp-searchrow"><label class="fp-search">${icon('search')}<input name="query" value="${esc(s.query)}" placeholder="Search accounts, HCPs or NPI" aria-label="Search targets"></label>${ib('sliders-horizontal','filters','Filter targets')}</div><div class="fp-flex fp-wrap">${link('State · '+(s.targetState||'All states'),'filters')}${link('City · '+(s.targetCity||'All cities'),'filters')}${link(s.kind==='hco'?'Type · '+s.type:'Specialty','filters')}${link('Sort · '+s.sort,'filters')}${link('Export','target-export')}</div><p class="fp-small fp-muted">${rows.length} of ${rows.length} ${s.kind==='hco'?'accounts':'HCPs'} · 2025</p>${s.replacing?`<div class="fp-note warn">Replace ${esc(byId(s.replacing.entity).name)}. Your route is kept.${link('Keep original visit','replace-cancel')}</div>`:''}${s.source==='new'?`<div class="fp-note">${s.near?esc(s.origin)+' · '+s.radius+' miles':[s.geoState,s.city].filter(Boolean).join(' · ')}${link('Change area','filters')}</div>`:''}${rows.map(liveTargetRow).join('')||`<div class="fp-empty">No targets match this scope.${b('Explore the territory','view:explore','fp-full fp-gap')}</div>`}<div class="live-paging">${b('‹ Previous','page:previous','', 'disabled')}<span>1–${rows.length} of ${rows.length}</span>${b('Next ›','page:next','','disabled')}</div></section>`;}
      function Vmap(){const rows=scoped(s);return `${liveShortcuts()}${codesControl()}<div class="fp-kicker">${esc(s.group)} · Opportunity Map · 2025</div><h1>${s.source==='new'?'Find someone new':'Opportunity Map'}</h1><p class="fp-small fp-muted">${s.source==='new'?'Facilities and doctors not in your targets yet.':s.view==='assigned'?'Assigned targets in '+esc(getScope(s))+'.':'Explore facilities and doctors in '+esc(getScope(s))+'.'}</p>${tabs([['hco','Accounts'],['hcp','Doctors']],s.kind,'kind')}<div class="live-mapfilters"><div>${b((s.near?'✓ ':'')+(s.kind==='hco'?'Hospitals':'Doctors')+' near me','near-toggle',s.near?'soft':'')}${s.near?b(esc(s.origin)+' · '+s.radius+' mi','filters'):b('State · '+s.geoState+' · '+(s.city||'All cities'),'filters')}</div>${s.kind==='hco'?link('Type · '+s.type,'filters'):link('Specialty','filters')}${!s.near?link('Save '+s.geoState+' as a territory','territory-from-search'):''}${link('Export','target-export')}</div>${map('discovery',true)}<div class="fp-flex fp-spread"><span class="fp-kicker">Heat map</span><div class="fp-pills">${[['pins','Pins'],['zip','ZIP'],['county','County'],['state','State']].map(([k,l])=>`<button class="fp-pill cursor-interaction" data-act="layer:${k}" aria-pressed="${s.mapLayer===k}">${l}</button>`).join('')}</div></div><p class="fp-small fp-muted">Numbered sample facilities · straight-line distance. Heat layers are illustrative.</p>${s.pin?lc('map-detail',sites[s.pin].name,'Selected map result',`${qr(['Procedure claims · 2025','Opportunity'],[fmt(vol(byId(s.pin),s)),cash(sites[s.pin].opportunity*factor(s))])}<div class="fp-actions">${b('Open account','entity:'+s.pin,'primary')}${b('HCPs here','site-hcps:'+s.pin)}${b('Add to territory','assign:'+s.pin)}${b('Choose visits','select:'+s.pin)}</div>`):''}<h2 class="fp-gap">${s.kind==='hco'?'Accounts':'Doctors'} in this scope</h2>${rows.map(liveTargetRow).join('')||'<div class="fp-empty">No matching new targets. Adjust the area or open your territories.</div>'}`;}
      function pageJump(items){return `<label class="live-jump">On this page<select name="pageJump" aria-label="Jump to profile section"><option value="">Choose a section…</option>${items.map(([k,l])=>`<option value="${k}">${l}</option>`).join('')}</select></label>`;}
      function profileHero(e){return `<div class="live-crumb">${link(s.screen==='hco'?'Targets':'Account','back')}<span>/</span><span>${esc(e.name)}</span></div><section class="live-profilehero"><div class="fp-kicker">${esc(e.kind==='hco'?e.type+' · '+e.state:e.specialty+' · NPI '+e.npi)}</div><div class="fp-flex"><span class="fp-initial">${initials(e)}</span><div class="fp-grow"><h1>${esc(e.name)}</h1><p class="fp-small fp-muted">${esc(e.kind==='hco'?e.city+', '+e.state+' · individual facility':S(e.id).name+' · '+e.city+', '+e.state)} · ${esc(s.group)} · 2025</p></div></div><div class="fp-flex fp-wrap">${tag(membershipLabel(e,s)?'✓ Target · '+membershipLabel(e,s):'Not in your targets',membershipLabel(e,s)?'blue':'')}${link('+ Add to territory','assign:'+e.id)}${link('+ Today’s route','select:'+e.id)}${membershipLabel(e,s)?link('Remove target','remove-target:'+e.id):''}</div></section>`;}
      function proActions(e){return `<div class="live-profileactions">${e.kind==='hco'?b(icon('file-chart-column')+' Generate leakage report','pro-report:'+e.id,'primary fp-full'):''}<div class="fp-flex fp-wrap">${b('+ Log a visit','log:'+e.id)}${b('↓ Save as PDF','brief-export:'+e.id)}${b('↓ Export','profile-export:'+e.id)}${e.kind==='hco'?b('◎ View on a map','profile-map:'+e.id):b(icon('mail')+' Email','email:'+e.id)}${b(icon('sparkles')+' Ask','ask:entity','soft')}${e.kind==='hcp'?b('↗ Full profile','provider-record:'+e.id):''}</div></div>`;}
      function sourceBrief(e,work=false){const text=s.prep[e.id];return lc('brief',work?'What to say':'AI brief',work?'Prepare before the conversation':'Read this first',`${work?`<div class="fp-fieldline">${select('Visit purpose','briefPurpose',s.purpose?.[e.id]||'General MSL Visit',['General MSL Visit','Referral network','Procedure growth','Robotic adoption','Value analysis'])}<div style="align-self:end;margin-bottom:12px">${b(text?'Write again':'Generate brief','generate-brief:'+e.id,'primary')}</div></div>`:`<div class="live-objective"><span class="fp-kicker">Objective</span><strong>${esc(s.purpose?.[e.id]||e.goal||'Understand the account’s opportunity and agree a next step.')}</strong></div>`}${text||!work?`<div class="fp-kicker fp-gap">What the claims say</div><p>${esc(e.name)} has <strong>${fmt(vol(e,s))}</strong> ${e.kind==='hcp'?'claims':'procedures'} in this scope, ${e.trend}% above 2024. ${e.kind==='hco'?(e.left/e.volume*100).toFixed(1)+'% of measured procedures left this account.':'Review both the sending and receiving referral network.'}</p><div class="fp-kicker fp-gap">What to open with</div><p>${esc(text||e.goal||'What changed in the procedure mix, and where would a follow-up briefing be most useful?')}</p>`:'<p class="fp-small fp-muted">Choose the purpose, then generate a briefing from the available evidence.</p>'}<div class="fp-pills">${['Dx','Px','Rx','Publications','Trials','Payments','Payer mix','Referrals','Affiliations'].map(x=>tag(x)).join('')}</div><div class="fp-flex fp-wrap">${!work?link('Write again','generate-brief:'+e.id):''}${link('Ask about this brief','prep:'+e.id)}${link('Edit / copy','brief-edit:'+e.id)}</div>`);}
      function sourceMix(e){const keys=s.group==='All codes'?(e.kind==='hcp'?e.codes:groups.slice(1)):[s.group],total=vol(e,s),rows=keys.map(k=>({key:k,n:vol(e,{...s,group:k})})).filter(x=>x.n).sort((a,b)=>b.n-a.n);return `<div class="fp-searchrow"><label class="fp-search">${icon('search')}<input name="mixSearch" data-entity="${e.id}" placeholder="Search codes" aria-label="Search procedure codes" value="${esc(s.mixSearch||'')}"></label></div>${liveTable(['Code / procedure','Claims','Share'],rows.filter(r=>!(s.mixSearch)||[r.key,...(CPT[r.key]||[])].join(' ').toLowerCase().includes(s.mixSearch.toLowerCase())).map(r=>[`<strong>${esc(CPT[r.key]?.[0]||r.key)}</strong><small>${esc(CPT[r.key]?.[1]||r.key)}</small>`,fmt(r.n),(r.n/(total||1)*100).toFixed(1)+'%']))}<p class="fp-small fp-muted fp-gap">Procedure claims · selected codes · 2025</p>`;}
      function yearly(e){const n=vol(e,s),ys=[Math.round(n*.72),Math.round(n*.82),Math.round(n/(1+e.trend/100)),n,Math.round(n*.38)];return chart(ys,['2022','2023','2024','2025','2026*'])+liveTable(['Year','Procedures','Patients','Charges'],ys.map((v,i)=>[i===4?'2026*':String(2022+i),fmt(v),fmt(Math.round(v*.88)),cash(v*.0008)]))+'<p class="fp-small fp-muted fp-gap">2026* is a partial year; claims are still flowing in. Patients are a separate measure from procedures.</p>';}
      function quarter(e){const left=e.left/e.volume,base=e.volume/4;return `<div class="live-quarter" role="img" aria-label="Kept and left procedures by quarter">${['Q1 24','Q2 24','Q3 24','Q4 24','Q1 25','Q2 25','Q3 25','Q4 25'].map((q,i)=>{const n=Math.round(base*(i<4?.86:1)*(1+(i%4-1.5)*.025)),l=Math.round(n*left);return `<div><span>${q}</span><i><b style="width:${100-left*100}%"></b><em style="width:${left*100}%"></em></i><small>${fmt(n-l)} / ${fmt(l)}</small></div>`;}).join('')}</div><p class="fp-small fp-muted">Blue: kept · orange: left. Recent quarters may still be incomplete.</p>`;}
      function destinationTable(e){const n=e.left,others=allHco.filter(h=>h.id!==e.id),rows=others.map((h,i)=>[link(esc(h.name),'entity:'+h.id),fmt(Math.round(n*(i?.32:.53))),cash(n*(i?.32:.53)*.0007),(i?'32%':'53%')]);rows.push(['Other facilities',fmt(n-Math.round(n*.53)-Math.round(n*.32)),cash(n*.15*.0007),'15%']);return liveTable(['Destination','Procedures','Billed','Share'],rows)+link('◎ Map destinations','profile-map:'+e.id);}
      function payments(e,work=false){if(!work)return proPayments(e);const key=e.id,q=live.payments[key]||'',total=e.kind==='hcp'?24800:126000,companies=['Aster Medical','Northstar Devices','Meridian Health','Summit Surgical','Other companies'],part=[.38,.27,.18,.11,.06];return `<div class="live-payment-total"><strong>$${fmt(total)}</strong><span>paid · ${companies.length} companies · 2024</span></div><label class="fp-search">${icon('search')}<input name="companySearch" data-entity="${e.id}" aria-label="Search companies" placeholder="Search companies" value="${esc(q)}"></label>${liveTable(['Company','Paid','Share'],companies.map((name,i)=>({name,i})).filter(x=>x.name.toLowerCase().includes(q.toLowerCase())).map(({name,i})=>[name,'$'+fmt(total*part[i]),Math.round(part[i]*100)+'%']))}<p class="fp-small fp-muted fp-gap">Illustrative CMS Open Payments · 2024; separate from claims period.</p>`;}
      function hcoSections(e){return sourceBrief(e)+lc('mix','Procedure mix','Top codes by claims · 2025',sourceMix(e)+`<details><summary class="cursor-interaction">By procedure group & performing specialty</summary><div class="fp-inside">${qr(['Surgery','Colorectal surgery','Other specialties'],['62%','24%','14%'])}</div></details>`)+lc('years','Procedure volume by year','At '+e.name,yearly(e))+lc('capacity','Capacity & profile','Latest hospital record',qr(['Staffed beds','Operating rooms','Surgeries a year (est.)','Discharges','Net patient revenue','Hospitals in the system','Ownership','Type'],[fmt(e.beds),fmt(Math.round(e.beds*.045)),fmt(e.volume*5),fmt(e.volume*4.2),cash(e.volume*.017),'3','Voluntary nonprofit',e.type]))+lc('robotic','Robotic-assist claims','Claims billed with S2900 · 2025 vs 2024',chart([268,312],['2024','2025'])+'<p class="fp-small fp-muted">Not every payer requires S2900. These claims do not count every robotic procedure.</p>')+lc('quarter','Leakage by quarter','All cases kept vs sent elsewhere · Q1 2024–Q4 2025',quarter(e))+lc('destinations','Where the cases go','Destinations of procedures that left since 2022',destinationTable(e))+lc('case-loss','Case loss by DRG','Hospital stays · a separate population from procedure claims',liveTable(['DRG / description','Kept','Left','Left %'],[['329 · Major bowel procedures','146','28','16.1%'],['330 · Major bowel procedures, complications','121','17','12.3%'],['393 · Other digestive diagnoses','198','21','9.6%']]))+lc('market','Market share within 100 miles','In-radius procedure share · 2025',qr([e.name,...allHco.filter(h=>h.id!==e.id).map(h=>h.name),'Other facilities'],[e.market+'%',...allHco.filter(h=>h.id!==e.id).map(h=>h.market+'%'),(100-allHco.reduce((n,h)=>n+h.market,0)).toFixed(1)+'%']))+lc('payments','Industry payments','Payments to affiliated HCPs',payments(e))+lc('notes','Notes & visits','Dated interactions and reports for this account',profileActivity(e))+lc('referrals','Referrals in and out','Patient referrals for these diagnoses · 2025',qr(['Referred in','Referred out','Net referrals'],['1,240','870','+370'])+b('HCPs at this account','hcotab:people'));
      }
      function Vhco(){const e=byId(s.id);return `${codesControl(true)}${profileHero(e)}<div class="live-tabs" role="tablist" aria-label="Account sections"><button role="tab" class="cursor-interaction" data-act="hcotab:overview" aria-selected="${s.hcoTab==='overview'}">Account overview</button><button role="tab" class="cursor-interaction" data-act="hcotab:people" aria-selected="${s.hcoTab==='people'}">HCPs at this account · ${scopeHcpsAt(e.id).length}</button></div>${proActions(e)}${s.hcoTab==='people'?lc('people','HCPs at '+e.name,'Ranked by selected-code claims · 2025',`<div class="live-kpis three">${metric('HCPs ranked',scopeHcpsAt(e.id).length,'Selected codes')}${metric('Specialties','2','selected codes')}${metric('Referring HCPs','3','2025')}</div>${scopeHcpsAt(e.id).map(liveTargetRow).join('')}<h3 class="fp-gap">Who refers here</h3>${allHcp.filter(p=>p.site!==e.id).slice(0,3).map(p=>detail(p.name,fmt(p.vol*.14),p.specialty)).join('')}${b('Explore HCPs near this account','near-site:'+e.id,'fp-full')}`):`<div class="live-kpis">${metric('Procedures',fmt(vol(e,s)),'+'+e.trend+'% · 2025')}${metric('Left the account',(e.left/e.volume*100).toFixed(1)+'%',fmt(e.left)+' / '+fmt(e.volume)+' · all cohort codes · 2025')}${metric('Opportunity',cash(e.opportunity*factor(s)),'billed charges · 2025')}${metric('In-radius share',e.market+'%','within 100 miles · 2025')}${metric('Leaking $',cash(e.leakingMoney),'billed charges · since 2022')}</div>${pageJump([['brief','AI brief'],['mix','Procedure mix'],['years','Volume by year'],['capacity','Capacity & profile'],['robotic','Robotic-assist claims'],['quarter','Leakage by quarter'],['destinations','Where cases go'],['case-loss','Case loss by DRG'],['market','Market share'],['payments','Industry payments'],['notes','Notes & visits'],['referrals','Referrals in and out']])}${hcoSections(e)}`}`;}
      function nearbyCard(e){return lc('nearby','Who else to see','At '+S(e.id).name+' and nearby · 2025',allHcp.filter(p=>p.id!==e.id).sort((a,b)=>(a.site===e.site?-1:1)-(b.site===e.site?-1:1)).slice(0,3).map(p=>`<div class="live-nearby"><div>${link(esc(p.name),'entity:'+p.id)}<small>${esc(p.specialty)} · ${fmt(vol(p,s))} claims</small></div>${b(s.selected.includes(p.id)?'✓ Today’s route':'Today’s route','select:'+p.id,s.selected.includes(p.id)?'soft':'')}</div>`).join('')+link('Explore all nearby HCPs','near-site:'+e.site));}
