      function openAIEntity(id,tab){if(!byId(id))return;s.mixSearch='';go(byId(id).kind==='hco'?'hco':'hcp',id);const key={volumes:'mix',leakage:'quarter',people:'people',referrals:'referrals',activity:'history',overview:'brief'}[tab]||'brief';if(byId(id).kind==='hco'&&tab==='people'){s.hcoTab='people';render();}else jumpTo(key);}
      function liveAct(action){const [a,...r]=action.split(':'),id=r.join(':');
        if(a==='profile-map'&&byId(id)?.kind==='hco'){open('account-map',{entity:id,lens:'opportunity'});return true;}if(a==='account-map-lens'){s.sheet.d.lens=id;render();return true;}if(a==='pin'&&s.sheet?.kind==='account-map'){s.sheet.d.pin=id;render();return true;}if(a==='remove-target'){const before=s.membership[id];delete s.membership[id];toast('Removed from territory. Route selection is kept.',()=>s.membership[id]=before);save();return true;}if(a==='ensure-add'){if(!s.selected.includes(id))act('select:'+id);else toast('Already in your route selection');return true;}if(a==='pdf-open'){go('report-doc');return true;}if(a==='report-stop-watch'){back();toast('Stopped watching. The report may still finish in Reports.');return true;}if(a==='provider-record'){open('provider-record',{entity:id});return true;}if(a==='entity'){s.mixSearch='';return false;}if(a==='select'&&byId(id)?.kind==='hco'){open('pick-hcps',{entity:id});return true;}
        if(a==='unified-search'){open('search',{unifiedQuery:''});return true;}if(a==='search-ask'){const q=s.sheet.d.unifiedQuery;s.sheet=null;ask('scope',null);s.askText=q;sendAsk();return true;}
        if(a==='all-codes'){open('code-list',{codePick:s.group});return true;}if(a==='code-apply'){s.group=s.sheet.d.codePick;s.sheet=null;render();save();return true;}
        if(a==='territory-new'){open('territory',{name:'',mode:'states',codes:[],zips:''});return true;}if(a==='plan-tomorrow'){switchDay('2026-10-29');s.nav='targets';go('targets');toast('Planning tomorrow. Today’s calls and records are kept.');return true;}if(a==='route-settings-save'){const d=s.sheet.d;if(!d.date||!d.origin.trim()){s.sheet.error='Choose a date and starting point.';render();return true;}if(d.date!==s.routeDate)switchDay(d.date);s.routeOrigin=d.origin;s.returnOrigin=d.returnOrigin;s.sheet=null;render();save();return true;}if(a==='territory-display'){s.territoryDisplay=id;render();save();return true;}if(a==='territory-coverage'){s.territoryCoverage=id;render();save();return true;}if(a==='territory-export'){open('export',{title:'Territory export',subtitle:'CSV export preview of named coverage.',text:'Territory,Coverage,Values\n'+s.territories.map(t=>t.name+','+t.mode+','+t.codes.join(' ')).join('\n')});return true;}if(a==='live-filter-save'){const d=s.sheet.d;Object.assign(s,d);if(s.source==='new'&&!d.near){s.geoState=d.targetState==='all'?'NY':d.targetState;s.targetState='all';s.targetCity='all';}s.sheet=null;s.pin=null;render(false);save();return true;}if(a==='protab'){const [mode,kind]=id.split('-');s.kind=kind;s.view=mode==='my'?'assigned':'explore';s.source='territories';s.query='';render();save();return true;}
        if(a==='add-targets'){s.source='new';s.view='explore';s.query='';open('filters',{near:s.near,origin:s.origin,radius:s.radius,geoState:s.geoState,city:s.city,group:s.group,type:s.type,specialty:s.specialty,sort:s.sort});return true;}
        if(a==='near-toggle'){s.near=!s.near;render();save();return true;}if(a==='territory-from-search'){open('territory',{name:s.geoState+' territory',mode:'states',codes:[s.geoState],zips:''});return true;}
        if(a==='field-start'){if(s.routeDraft)act('route-save');if(!s.routeDraft)act('start');return true;}if(a==='field-step'){if(id==='Scope')open('scope');else if(id==='Plan'){s.nav='targets';go('targets');}else if(id==='Route')go('route');else if(id==='Work')act('resume:'+s.currentVisit);else go('recap');return true;}
        if(a==='origin-use'){if(!s.routeStart?.trim()){toast('Enter a starting address or city.');return true;}s.routeOrigin=s.routeStart;toast('Starting point set for this preview');save();return true;}if(a==='origin-sample'){s.routeOrigin='Columbus Circle, New York';s.routeStart=s.routeOrigin;toast('Using the sample start location');save();return true;}
        if(a==='facility-up'||a==='facility-down'){if(!s.routeDraft)s.routeDraft=copy(s.plan);const gs=grouped(s.routeDraft),i=gs.findIndex(g=>g.site===id),j=i+(a==='facility-up'?-1:1);if(j>=0&&j<gs.length){[gs[i],gs[j]]=[gs[j],gs[i]];s.routeDraft=gs.flatMap(g=>g.visits);}render();save();return true;}
        if(a==='run-sheet'){open('run-sheet');return true;}if(a==='call'){const v=s.plan.find(v=>v.id===id);s.currentVisit=id;s.id=v.entity;s.sheet=null;s.screen='visit';live.preTab='overview';render(false);save();return true;}
        if(a==='back-call'){const arr=s.plan.filter(v=>v.status!=='cancelled'),i=arr.findIndex(v=>v.id===s.currentVisit);if(i>0)liveAct('call:'+arr[i-1].id);return true;}
        if(a==='pretab'){live.preTab=id;s.preReadTab=id;render(false);save();return true;}if(a==='done-next'||a==='skip-visit'){live.preTab='overview';s.preReadTab='overview';return false;}
        if(a==='full-profile'){openAIEntity(id,'overview');return true;}if(a==='full-network'){openAIEntity(id,'referrals');return true;}
        if(a==='replace-direct'){const v=s.plan.find(v=>v.id===s.currentVisit)||s.plan.find(v=>v.status==='planned');if(v){s.currentVisit=v.id;act('replace');}else toast('Start a route to choose a replacement.');return true;}
        if(a==='weekday'){live.week=id;render();return true;}if(a==='calendar-day'){open('export',{title:'Hospital activity',subtitle:'Historical claim-volume preview, not availability.',text:`${live.month+1}/${id}/${live.year} · ${S(s.id).name}\nTypical weekday activity in the selected sample.`});return true;}
        if(a==='generate-brief'){const e=byId(id);s.prep[id]=`Review ${e.kind==='hcp'?'the procedure mix and referral network':'leakage destinations and account volume'}. ${e.goal||'Ask what changed and agree on a useful next step.'}`;toast('Brief updated from the selected sample evidence');save();return true;}
        if(a==='log'){openLog(id);s.sheet.d.outcome=s.sheet.d.outcome||'Met';render();return true;}if(a==='note-type'){s.sheet.d.type=id;render();return true;}
        if(a==='field-save-note'){if(!s.sheet.d.text.trim()){s.sheet.error='Add or dictate a note first.';render();return true;}saveNote(false);return true;}
        if(a==='booking-length'){s.sheet.d.duration=Number(id);render();return true;}
        if(a==='pro-report'){const running=s.reports.find(r=>r.status==='generating');if(running){s.reportId=running.id;go('report');return true;}const e=byId(id),report={id:'r'+Date.now(),entity:id,group:s.group,title:e.name+' · '+s.group,radius:'100',date:TODAY,status:'generating',shared:false};s.reports.push(report);s.reportId=report.id;go('report');setTimeout(()=>{report.status=prefs.reportMode==='Report fails'?'failed':'ready';if(['report','reports'].includes(s.screen))render();save();},2200);save();return true;}
        if(a==='profile-export'||a==='target-export'){const e=byId(id);open('export',{title:'Export data',subtitle:'Export preview of the current scope.',text:e?e.name+' · '+s.group+' · 2025\nProcedure claims: '+fmt(vol(e,s)):scoped(s).map(e=>e.name+' · '+fmt(vol(e,s))).join('\n')});return true;}
        if(a==='contact'){open('export',{title:'Contact details',subtitle:'Illustrative professional contact information.',text:byId(id).name+'\n(212) 555-0101\n'+S(id).name});return true;}
        if(a==='email'){const e=byId(id);open('email',{entity:id,to:e.name.replace('Dr. ','').toLowerCase().replace(' ','.')+'@example.com',subject:'Follow-up discussion · '+s.group,body:`Hello ${e.name.replace('Dr. ','')},\n\n${s.prep[id]||e.goal}\n\nWould a brief discussion on this be useful?\n\nAlex`});return true;}
        if(a==='email-copy'){open('export',{title:'Copy email draft',text:s.sheet.d.subject+'\n\n'+s.sheet.d.body});return true;}
        if(a==='zip-upload'){open('csv',{name:'',csv:''});return true;}if(a==='zip-sample'){s.sheet.d.csv='territory,zip\nManhattan North,10019\nManhattan North,10029';s.sheet.d.name='Manhattan North';render();return true;}if(a==='zip-review'){const d=s.sheet.d,zips=d.csv.match(/\b\d{5}\b/g)||[];if(!d.name.trim()||!zips.length){s.sheet.error='Provide a territory name and valid ZIP codes.';render();return true;}open('territory',{name:d.name,mode:'zips',codes:[],zips:[...new Set(zips)].join(', ')});return true;}
        if(a==='prompt'){s.askText=id;sendAsk();return true;}if(a==='ask-send'){sendAsk();return true;}if(a==='filters'){return false;}if(a==='filter-reset'){Object.assign(s.sheet.d,{targetState:'all',targetCity:'all'});s.targetState='all';s.targetCity='all';return false;}if(a==='ask-clear'||a==='ask-new'){s.turns=[];live.about=null;render();save();return true;}
        if(a==='ai-open'){const parts=id.split(':');openAIEntity(parts[0],parts[1]);return true;}if(a==='ai-do'){const turn=s.turns[Number(id)],d=turn?.result?.doThis;if(!d)return true;if(d.action==='openProfile')openAIEntity(d.data.id,d.data.tab);else if(d.action==='command')act(d.data.command);else if(d.action==='report'){s.reportId=d.data.id;go('report');}else if(d.action==='tab'){s.activityTab='records';go('activity');}else go('route');return true;}
        if(a==='use-ai-brief'){const t=s.turns[Number(id)],e=byId(t.about||t.result.about);if(!e)return true;s.prep[e.id]=t.result.summary;const v=s.askContext.visit;s.id=e.id;if(v&&s.plan.find(x=>x.id===v)?.entity===e.id){s.currentVisit=v;live.preTab='overview';go('visit',e.id);}else openAIEntity(e.id,'brief');toast('Brief applied. No visit was marked done.');save();return true;}
        if(a==='ask-retry'){const q=s.turns[Number(id)].q;s.turns.splice(Number(id),1);s.askText=q;sendAsk();return true;}
        if(a==='hands-free'){live.handsFree=!live.handsFree;live.voice=live.handsFree?'listening':'idle';live.voiceText='';render();return true;}if(a==='read-toggle'){live.readAloud=!live.readAloud;render();return true;}
        if(a==='ask-voice'){live.voice='listening';live.voiceText='';render();return true;}if(a==='voice-sample'){live.voiceText='Brief me on '+(byId(s.askContext.id)?.name||'Dr. Maya Patel');render();return true;}if(a==='voice-done'){if(!live.voiceText)live.voiceText='Who should I see today?';s.askText=live.voiceText;live.voice='idle';sendAsk('voice');return true;}if(a==='voice-cancel'){live.voice='idle';live.handsFree=false;live.voiceText='';render();return true;}if(a==='read-turn'){const t=s.turns[Number(id)];live.voice='speaking';live.voiceText=t.result.summary;render();return true;}
        return false;
      }
      app.addEventListener('input',e=>{const el=e.target;if(el.name==='territoryQuery'){s.territoryQuery=el.value;render();}if(el.name==='mixSearch'){s.mixSearch=el.value;render();}if(el.name==='companySearch'){live.payments[el.dataset.entity]=el.value;render();}if(el.name==='routeStart')s.routeStart=el.value;if(s.sheet?.kind==='search'&&el.name==='unifiedQuery')render();if(s.sheet?.kind==='log'&&el.name==='text'){const saveBtn=app.querySelector('[data-act="field-save-note"]');if(saveBtn)saveBtn.disabled=!el.value.trim();}});
      app.addEventListener('change',e=>{const el=e.target;if(el.name==='pageJump'&&el.value)jumpTo(el.value);if(el.name==='briefPurpose'){s.purpose={...s.purpose,[s.id]:el.value};save();}if(el.name==='calendarMonth'){live.month=Number(el.value);render();}if(el.name==='calendarYear'){live.year=Number(el.value);render();}if(el.name==='file'&&s.sheet?.kind==='csv'&&el.files?.[0])el.files[0].text().then(text=>{if(s.sheet?.kind==='csv'){s.sheet.d.csv=text.slice(0,3000);render();}});});
